-- 004: one-off import of the clerk's Excel marks (Invoices 20260612 1 - Copy 2.xlsx), NOT YET APPLIED.
-- Colour of the invoice-number cell in her sheet: green = found, red = missing, black/blue/purple = not checked.
-- Rows 1059765 and above (newer than her "STOPPED AT 1059764" note) are left unchecked.
-- Imported marks are stamped "Imported from Excel" instead of a person.

-- The stamp trigger only overrides who/when for real signed-in users, so this import can label itself.
create or replace function public.mi_checks_stamp() returns trigger
  language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    new.checked_by      := auth.uid();
    new.checked_by_name := coalesce((select (public.ar_my_access())->>'name'), 'unknown');
  end if;
  new.updated_at := now();
  if tg_op = 'INSERT' or new.status is distinct from old.status then new.checked_at := now(); end if;
  return new;
end $$;

create temp table mi_import_stage(ref text, st text, note text);
