-- Check first: how many sheet rows exist in the invoices table?
-- select st, count(*), count(i.reference_number) as in_db from mi_import_stage s left join public.invoices i on i.reference_number = s.ref group by st;

insert into public.mi_checks (reference_number, status, note, checked_by_name, checked_at)
select i.reference_number, case s.st when 'f' then 'found' else 'missing' end, s.note, 'Imported from Excel', now()
from mi_import_stage s join public.invoices i on i.reference_number = s.ref
on conflict (reference_number) do nothing;
